import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;public class Main {    static int N;    static int[] A;    static long totalSum;    public static void main(String[] args) throws java.lang.Exception {        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        PrintWriter out = new PrintWriter(System.out);        StringTokenizer st = null;        String line = br.readLine();        if (line == null) return;        int T = Integer.parseInt(line.trim());        while (T-- > 0) {            N = Integer.parseInt(br.readLine().trim());            A = new int[N];            totalSum = 0;            solve(0);            out.println(totalSum);        }        out.flush();    }    static void solve(int idx) {        if (idx == N) {            long count = 0;            for (int i = 1; i < N - 1; i++) {                if ((A[i] > A[i - 1] && A[i] > A[i + 1]) || (A[i] < A[i - 1] && A[i] < A[i + 1])) {                    count++;                }            }            totalSum += count;            return;        }        for (int val = 0; val <= 2; val++) {            A[idx] = val;            solve(idx + 1);        }    }}